changeSet.sql:
ALTER TABLE krrg_employees ADD COLUMN citizenship_id BIGINT;
ALTER TABLE krrg_employees
    ADD CONSTRAINT fk_employees__citizenship
        FOREIGN KEY (citizenship_id) REFERENCES krrg_location_states(id) ON DELETE RESTRICT;

ALTER TABLE krrg_employees ADD COLUMN city_id BIGINT;
ALTER TABLE krrg_employees
    ADD CONSTRAINT fk_employees__city
        FOREIGN KEY (city_id) REFERENCES krrg_location_cities(id) ON DELETE RESTRICT;

DO $$
DECLARE
r RECORD;
BEGIN
FOR r IN
SELECT conname, conrelid::regclass AS tbl
FROM pg_constraint
WHERE confrelid = 'krrg_employee_employee'::regclass
          AND contype = 'f'
    LOOP
        EXECUTE format('ALTER TABLE %s DROP CONSTRAINT IF EXISTS %I', r.tbl, r.conname);
END LOOP;
END $$;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_profile' AND column_name = 'employee_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_profile__employee') THEN
ALTER TABLE krrg_employee_profile
    ADD CONSTRAINT fk_employee_profile__employee
        FOREIGN KEY (employee_id) REFERENCES krrg_employees(id);
END IF;
END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_languages' AND column_name = 'employee_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_languages__employee') THEN
ALTER TABLE krrg_employee_languages
    ADD CONSTRAINT fk_employee_languages__employee
        FOREIGN KEY (employee_id) REFERENCES krrg_employees(id) ON DELETE CASCADE;
END IF;
END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_contacts' AND column_name = 'employee_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_contacts__employee') THEN
ALTER TABLE krrg_employee_contacts
    ADD CONSTRAINT fk_employee_contacts__employee
        FOREIGN KEY (employee_id) REFERENCES krrg_employees(id) ON DELETE CASCADE;
END IF;
END IF;
END $$;

DROP TABLE IF EXISTS krrg_employee_employee;

-- 1. Переименовываем, если нужно
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'krrg_employee_profile')
       AND NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'krrg_employee_profiles') THEN
ALTER TABLE krrg_employee_profile RENAME TO krrg_employee_profiles;
END IF;
END $$;

-- 2. Добавляем created_at/updated_at, если их нет
ALTER TABLE krrg_employee_profiles ADD COLUMN IF NOT EXISTS created_at TIMESTAMP(6);
ALTER TABLE krrg_employee_profiles ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP(6);

-- 1. Переносим данные из старой в новую (без created_at/updated_at, чтобы не зависеть от их наличия)
INSERT INTO krrg_employee_profiles (id, version, employee_id, name)
SELECT id, version, employee_id, name
FROM krrg_employee_profile
    ON CONFLICT (id) DO NOTHING;

-- 2. Удаляем FK, ссылающиеся на старую таблицу
DO $$
DECLARE
r RECORD;
BEGIN
FOR r IN
SELECT conname, conrelid::regclass AS tbl
FROM pg_constraint
WHERE confrelid = 'krrg_employee_profile'::regclass
          AND contype = 'f'
    LOOP
        EXECUTE format('ALTER TABLE %s DROP CONSTRAINT IF EXISTS %I', r.tbl, r.conname);
END LOOP;
END $$;

-- 3. Создаём FK на krrg_employee_profiles для таблиц, которые ссылались на старую
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_profile_direction' AND column_name = 'profile_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_profile_direction__profile') THEN
ALTER TABLE krrg_employee_profile_direction
    ADD CONSTRAINT fk_employee_profile_direction__profile
        FOREIGN KEY (profile_id) REFERENCES krrg_employee_profiles(id);
END IF;
END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_profile_educationtype' AND column_name = 'profile_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_profile_educationtype__profile') THEN
ALTER TABLE krrg_employee_profile_educationtype
    ADD CONSTRAINT fk_employee_profile_educationtype__profile
        FOREIGN KEY (profile_id) REFERENCES krrg_employee_profiles(id);
END IF;
END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_profile_organization' AND column_name = 'profile_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_profile_organization__profile') THEN
ALTER TABLE krrg_employee_profile_organization
    ADD CONSTRAINT fk_employee_profile_organization__profile
        FOREIGN KEY (profile_id) REFERENCES krrg_employee_profiles(id);
END IF;
END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_profile_skill' AND column_name = 'profile_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_profile_skill__profile') THEN
ALTER TABLE krrg_employee_profile_skill
    ADD CONSTRAINT fk_employee_profile_skill__profile
        FOREIGN KEY (profile_id) REFERENCES krrg_employee_profiles(id);
END IF;
END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_profile_specialty' AND column_name = 'profile_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_profile_specialty__profile') THEN
ALTER TABLE krrg_employee_profile_specialty
    ADD CONSTRAINT fk_employee_profile_specialty__profile
        FOREIGN KEY (profile_id) REFERENCES krrg_employee_profiles(id);
END IF;
END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_name = 'krrg_employee_profile_university' AND column_name = 'profile_id') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_profile_university__profile') THEN
ALTER TABLE krrg_employee_profile_university
    ADD CONSTRAINT fk_employee_profile_university__profile
        FOREIGN KEY (profile_id) REFERENCES krrg_employee_profiles(id);
END IF;
END IF;
END $$;

-- 4. Удаляем старую таблицу
DROP TABLE IF EXISTS krrg_employee_profile;

rollback.sql:
ALTER TABLE krrg_employee_profiles ADD COLUMN grade_id BIGINT;
ALTER TABLE krrg_employee_profiles
    ADD CONSTRAINT fk_krrg_employee_profile_grade
        FOREIGN KEY (grade_id) REFERENCES krrg_employee_grade(id);

changeSet.sql:
INSERT INTO krrg_employee_profile_skills (id, profile_id, skill_id)
SELECT id, profile_id, skill_id
FROM krrg_employee_profile_skill
    ON CONFLICT (id) DO NOTHING;

DROP TABLE IF EXISTS krrg_employee_profile_skill;
